-- 110: Geauga Lake (Aurora, Ohio; RCDB "Geauga Lake & Wildwater Kingdom"),
-- closed 16 Sep 2007 - a new park at Carter's coords, with the five coasters
-- he sent from RCDB, 2026-10-31: Beaver Land Mine Ride (Zierer Tivoli,
-- 2000-2007), Big Dipper (wood, 1925-2007), Corkscrew (Arrow, 1978-1995),
-- Dominator (B&M Floorless, 2000-2007), Double Loop (Arrow, 1977-2007).
-- Relocation linked: Dominator -> Dominator at Kings Dominion (home).
-- Not linked: Beaver Land -> Papea Parc, Corkscrew -> MGM Dizzee World - not
-- parks here. Thunderhawk (Michigan's Adventure) waits for its Geauga page.
-- Safe to run twice.
INSERT OR IGNORE INTO same_ride (coaster, ride) SELECT c.id, h.id FROM coasters c, coasters h WHERE h.name = 'Dominator' AND h.park = 'Kings Dominion' AND (c.id = h.id OR (c.name = 'Dominator' AND c.park = 'Geauga Lake'));
