INSERT INTO parks (name, lat, lon, region) SELECT 'Geauga Lake', 41.3446, -81.3636, 'Ohio, US' WHERE NOT EXISTS (SELECT 1 FROM parks WHERE name = 'Geauga Lake');
INSERT INTO coasters (id, name, park, type, manu, model, h, s, l, inv, dur, yr, opened, openedPrec, closed, closedPrec, laps) SELECT (SELECT COALESCE(MAX(id),0)+1 FROM coasters), 'Beaver Land Mine Ride', 'Geauga Lake', 'Steel', 'Zierer', 'Zierer Tivoli', 26.3, 22.4, 1181.1, 0, NULL, 2000, '2000-05-05', 'day', '2007-09-16', 'day', 1 WHERE NOT EXISTS (SELECT 1 FROM coasters WHERE name = 'Beaver Land Mine Ride' AND park = 'Geauga Lake');
INSERT INTO activity (at, actor, kind, subject, n, detail) SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now'), NULL, 'coaster_added', c.name, NULL, json_object('id', c.id, 'park', c.park) FROM coasters c WHERE c.name = 'Beaver Land Mine Ride' AND c.park = 'Geauga Lake' AND NOT EXISTS (SELECT 1 FROM activity a WHERE a.kind = 'coaster_added' AND json_extract(a.detail, '$.id') = c.id);
